    @Override
    public void release(@NotNull DBPDataSourceTask user) {
        synchronized (users) {
            if (!users.remove(user)) {
                if (!isDisposed()) {
                    log.debug("Datasource user '" + user + "' is not registered in datasource '" + getName() + "'");
                }
            }
        }
    }

